// Adapters must verify provider signatures before invoking this webhook.
const body = $json.body ?? $json;
const header = $json.headers ?? {};
const supplied = header['x-cs-secret'] ?? header['X-Cs-Secret'];
if (!$env.CS_TENANT_SECRET || supplied !== $env.CS_TENANT_SECRET) return [{json:{stop:true,status:401,error:'unauthorized'}}];
const channel = $input.first().json.webhookUrl?.includes('/email') ? 'email' : $input.first().json.webhookUrl?.includes('/social') ? 'social' : 'chat';
const text = String(body.message ?? body.text ?? body.subject ?? '').trim();
const event_id = String(body.event_id ?? body.id ?? '');
const tenant_id = String(body.tenant_id ?? 'default');
const customer_id = String(body.customer_id ?? body.from ?? body.sender_id ?? '').trim();
if (!event_id || !customer_id || !text || text.length > 12000) return [{json:{stop:true,status:400,error:'event_id, customer_id and non-empty message (max 12000 chars) are required'}}];
return [{json:{tenant_id,channel,event_id,customer_id,message:text,metadata:body.metadata ?? {},received_at:new Date().toISOString()}}];

const request=$node['Normalize and validate'].json; const raw=$json.message?.content ?? $json.response?.message?.content ?? ''; let a; try { a=JSON.parse(raw); } catch { a={intent:'other',confidence:0,reply:'I’m connecting you with a specialist.',needs_human:true,reason:'invalid_model_output',citations:[]}; }
const allowed=['faq','order','complaint','other']; if(!allowed.includes(a.intent)) a.intent='other';
const risky=/(password|card|cvv|refund|cancel|chargeback|change.{0,25}address|legal|lawyer|police|suicide|harm|gdpr|delete my data)/i.test(request.message);
const sources=$node['Retrieve approved knowledge'].all().map(i=>i.json.source).filter(Boolean);
const badFaq=a.intent==='faq' && (!Array.isArray(a.citations)||!a.citations.some(x=>sources.includes(x)));
a.needs_human=Boolean(a.needs_human)||Number(a.confidence)<0.78||risky||badFaq||$node['Persist and fetch memory'].json.status==='waiting_human';
a.reason=a.reason || (badFaq?'missing_approved_citation':risky?'sensitive_request':a.needs_human?'low_confidence':'');
a.reply=String(a.reply||'I’m connecting you with a specialist.').slice(0,3000);
return [{json:{...request,conversation_id:$node['Persist and fetch memory'].json.conversation_id,decision:a,approved_sources:sources}}];
